import Breadcrumbs from '@jetbrains/ring-ui-built/components/breadcrumbs/breadcrumbs'
import type {EntryPointProps} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import {useLocation} from 'react-router'

import {getAgentPoolIdFromUrl, getAgentTypeIdFromUrl} from '../../../hooks/routes'
import {getAgentHref, getAgentPoolHref, getAgentTypeHref} from '../../../routes'
import type {AgentsPagesAgentTypesQuery} from '../../pages/AgentsPages/__generated__/AgentsPagesAgentTypesQuery.graphql'
import {agentTypesQuery} from '../../pages/AgentsPages/AgentsPages.queries'
import {dropCommonPrefix} from '../../pages/AgentsPages/AgentsPages.utils'
import BreadcrumbsLink from '../Breadcrumbs/BreadcrumbsLink/BreadcrumbsLink'

import type {AgentDomainBreadcrumbsAgentQuery} from './__generated__/AgentDomainBreadcrumbsAgentQuery.graphql'
import {agentQuery} from './AgentDomainBreadcrumbs.queries'

type Queries = {
  agent: AgentDomainBreadcrumbsAgentQuery
  agentTypes: AgentsPagesAgentTypesQuery
}

export default function AgentDomainBreadcrumbs({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const {agent} = usePreloadedQuery(agentQuery, queries.agent)
  const {agentPoolsRest} = usePreloadedQuery(agentTypesQuery, queries.agentTypes)
  const location = useLocation()
  const poolId = getAgentPoolIdFromUrl(location.pathname) ?? agent?.pool?.id
  const agentTypeId = getAgentTypeIdFromUrl(location.pathname) ?? agent?.typeId
  let pool
  let agentType
  for (const agentPool of agentPoolsRest?.agentPool ?? []) {
    if (poolId != null && agentPool.id !== poolId) {
      continue
    }
    const matchingAgentType = agentPool.agentTypes?.agentType?.find(({id}) => id === agentTypeId)
    if (agentPool.id === poolId || matchingAgentType != null) {
      pool = agentPool
      agentType = matchingAgentType
      break
    }
  }

  return (
    <Breadcrumbs>
      {pool && (
        <BreadcrumbsLink
          active={agentType == null}
          name={pool.name ?? ''}
          to={getAgentPoolHref(pool.id)}
        />
      )}
      {agentType?.isCloud && (
        <BreadcrumbsLink
          active={agent == null}
          name={agentType.name ?? ''}
          to={getAgentTypeHref(agentType.id)}
        />
      )}
      {agent && (
        <BreadcrumbsLink
          active
          name={
            (agentType?.isCloud && agentType.name != null && agent.name != null
              ? dropCommonPrefix(agentType.name, agent.name)
              : agent.name) ?? ''
          }
          to={getAgentHref(agent.id)}
        />
      )}
    </Breadcrumbs>
  )
}
export type AgentDomainBreadcrumbsComponent = typeof AgentDomainBreadcrumbs
